export interface ChatAnnouncerProps {
  /** A reply is being generated. */
  streaming: boolean;
  /** Plain text of the latest completed reply (announced once, when streaming ends). */
  lastReply?: string;
  /** Who is replying, used in the "is responding" status. */
  author?: string;
  /** Max characters of the completed reply to announce. */
  maxLength?: number;
}

/**
 * Screen-reader strategy for streaming: the thread itself is not a live region (it would
 * re-announce every token). This single polite, atomic status says "Assistant is responding…"
 * when a stream starts and reads the finished reply once when it ends.
 */
export function ChatAnnouncer({ streaming, lastReply, author = 'Assistant', maxLength = 600 }: ChatAnnouncerProps) {
  let text = '';
  if (streaming) text = `${author} is responding…`;
  else if (lastReply) text = lastReply.length > maxLength ? `${lastReply.slice(0, maxLength)}…` : lastReply;
  return (
    <div role="status" aria-live="polite" aria-atomic="true" className="sr-only">
      {text}
    </div>
  );
}

import { Avatar, IconButton, SimpleTooltip, cn, getInitials } from '@gntik-ai/ui';
import { Check, Copy, RotateCcw, Sparkles, ThumbsDown, ThumbsUp, Wrench } from 'lucide-react';
import { useId, type ReactNode, type Ref } from 'react';
import { formatTime } from '../utils/format';
import { useCopy } from '../utils/useCopy';
import { chatMessageStyles as s } from './chatMessage.variants';

export type ChatRole = 'user' | 'assistant' | 'system' | 'tool';
export type ChatFeedback = 'up' | 'down' | null;

export interface ChatMessageProps {
  role: ChatRole;
  /** Display name; defaults per role ("You", "Assistant", "System", "Tool"). */
  author?: string;
  /** Replaces the default avatar. Pass `null` to hide it. */
  avatar?: ReactNode;
  /** When the message was sent. A Date renders as a local short time. */
  timestamp?: Date | string;
  /** The body: a string, a <Markdown>, a ToolCallCard… */
  children?: ReactNode;
  /** Text is still arriving: hides the actions, marks the message busy, shows typing dots while empty. */
  streaming?: boolean;
  /** Plain text to copy; shows the Copy action. */
  copyText?: string;
  /** Shows the Retry action (assistant replies). */
  onRetry?: () => void;
  /** Current feedback (controlled). */
  feedback?: ChatFeedback;
  /** Shows the thumbs; called with the new value (clicking the active thumb clears it). */
  onFeedback?: (value: ChatFeedback) => void;
  /** Extra actions appended to the action group. */
  actions?: ReactNode;
  /** Keep the actions visible instead of revealing them on hover/focus. */
  alwaysShowActions?: boolean;
  className?: string;
  ref?: Ref<HTMLElement>;
}

const DEFAULT_AUTHOR: Record<ChatRole, string> = { user: 'You', assistant: 'Assistant', system: 'System', tool: 'Tool' };

function DefaultAvatar({ role, author }: { role: ChatRole; author: string }) {
  if (role === 'assistant') return <Avatar size="sm" tone="primary" fallback={<Sparkles size={15} aria-hidden />} />;
  if (role === 'tool') return <Avatar size="sm" tone="secondary" fallback={<Wrench size={14} aria-hidden />} />;
  // Decorative: the author name is already shown next to it.
  return <Avatar size="sm" tone="secondary" initials={getInitials(author)} />;
}

/**
 * One turn in a conversation. User turns are right-aligned bubbles, assistant turns are
 * full-width prose, system notes are centred pills and tool turns hold a ToolCallCard. Copy,
 * retry and feedback actions appear on hover or keyboard focus and are reachable with Tab.
 */
export function ChatMessage({
  role,
  author,
  avatar,
  timestamp,
  children,
  streaming = false,
  copyText,
  onRetry,
  feedback = null,
  onFeedback,
  actions,
  alwaysShowActions = false,
  className,
  ref,
}: ChatMessageProps) {
  const id = useId();
  const name = author ?? DEFAULT_AUTHOR[role];
  const v = s.role[role];
  const { copied, copy } = useCopy();
  const isEmpty = children === undefined || children === null || children === '';
  const time =
    timestamp instanceof Date ? (
      <time dateTime={timestamp.toISOString()} className={s.time}>
        {formatTime(timestamp)}
      </time>
    ) : timestamp ? (
      <span className={s.time}>{timestamp}</span>
    ) : null;
  const hasActions = !streaming && role !== 'system' && (copyText !== undefined || onRetry || onFeedback || actions);
  const showAvatar = role !== 'system' && avatar !== null;

  return (
    <article
      ref={ref}
      aria-labelledby={`${id}-author`}
      aria-busy={streaming || undefined}
      data-role={role}
      data-streaming={streaming || undefined}
      className={cn(s.root, v.root, className)}
    >
      {showAvatar && <div className={s.avatar}>{avatar ?? <DefaultAvatar role={role} author={name} />}</div>}
      <div className={cn(s.body, v.body)}>
        <div className={cn(s.meta, v.meta)}>
          <span id={`${id}-author`} className={s.author}>
            {name}
          </span>
          {time}
        </div>
        <div className={cn(s.content, v.content)}>
          {streaming && isEmpty ? (
            <span className={s.typing}>
              <span className={s.typingDot} />
              <span className={cn(s.typingDot, '[animation-delay:150ms]')} />
              <span className={cn(s.typingDot, '[animation-delay:300ms]')} />
              <span className="sr-only">{name} is thinking</span>
            </span>
          ) : (
            children
          )}
        </div>
        {hasActions && (
          <div role="group" aria-label={`Actions for ${name} message`} className={cn(s.actions, alwaysShowActions && s.actionsVisible)}>
            {copyText !== undefined && (
              <SimpleTooltip content={copied ? 'Copied' : 'Copy'}>
                <IconButton size="sm" icon={copied ? Check : Copy} label={copied ? 'Copied' : 'Copy message'} onClick={() => void copy(copyText)} />
              </SimpleTooltip>
            )}
            {onRetry && (
              <SimpleTooltip content="Retry">
                <IconButton size="sm" icon={RotateCcw} label="Retry" onClick={onRetry} />
              </SimpleTooltip>
            )}
            {onFeedback && (
              <>
                <SimpleTooltip content="Good response">
                  <IconButton
                    size="sm"
                    icon={ThumbsUp}
                    label="Good response"
                    aria-pressed={feedback === 'up'}
                    className={cn(feedback === 'up' && 'text-primary-text')}
                    onClick={() => onFeedback(feedback === 'up' ? null : 'up')}
                  />
                </SimpleTooltip>
                <SimpleTooltip content="Bad response">
                  <IconButton
                    size="sm"
                    icon={ThumbsDown}
                    label="Bad response"
                    aria-pressed={feedback === 'down'}
                    className={cn(feedback === 'down' && 'text-destructive-text')}
                    onClick={() => onFeedback(feedback === 'down' ? null : 'down')}
                  />
                </SimpleTooltip>
              </>
            )}
            {actions}
          </div>
        )}
      </div>
    </article>
  );
}

/** Slot classes for ChatMessage, per role. */
export const chatMessageStyles = {
  root: 'group/message relative flex gap-3 outline-none',
  avatar: 'mt-0.5 shrink-0',
  body: 'flex min-w-0 flex-1 flex-col gap-1',
  meta: 'flex items-baseline gap-2 text-[12px] leading-5',
  author: 'font-semibold text-foreground',
  time: 'font-mono text-[11px] text-muted-foreground',
  content: 'min-w-0 text-[14px] leading-[1.7] text-foreground',
  actions: [
    'flex items-center gap-0.5 transition-opacity motion-reduce:transition-none',
    'opacity-0 group-hover/message:opacity-100 group-focus-within/message:opacity-100 [@media(hover:none)]:opacity-100',
  ].join(' '),
  actionsVisible: 'opacity-100',
  typing: 'inline-flex h-6 items-center gap-1',
  typingDot: 'size-1.5 rounded-full bg-muted-foreground animate-pulse motion-reduce:animate-none',
  role: {
    user: {
      root: 'flex-row-reverse',
      body: 'items-end',
      meta: 'flex-row-reverse',
      content: 'max-w-[85%] rounded-2xl rounded-se-md bg-secondary px-4 py-2.5 whitespace-pre-wrap [overflow-wrap:anywhere]',
    },
    assistant: { root: '', body: '', meta: '', content: '' },
    system: {
      root: 'justify-center',
      body: 'items-center',
      meta: 'sr-only',
      content: 'rounded-full border border-border bg-card px-3 py-1 text-center text-[12px] leading-5 text-muted-foreground',
    },
    tool: { root: '', body: '', meta: '', content: 'text-[13px]' },
  },
} as const;

export { ChatMessage, type ChatMessageProps, type ChatRole, type ChatFeedback } from './ChatMessage';
export { ChatAnnouncer, type ChatAnnouncerProps } from './ChatAnnouncer';
export { chatMessageStyles } from './chatMessage.variants';
export { doc as chatMessageDoc } from './ChatMessage.doc';

/** "840 ms" below a second, "2.4 s" below a minute, "1 m 05 s" above. */
export function formatDuration(ms: number) {
  if (ms < 1000) return `${Math.round(ms)} ms`;
  if (ms < 60_000) return `${(ms / 1000).toFixed(1)} s`;
  const m = Math.floor(ms / 60_000);
  const s = Math.round((ms % 60_000) / 1000);
  return `${m} m ${String(s).padStart(2, '0')} s`;
}

/** "12 KB", "3.4 MB". */
export function formatBytes(bytes: number) {
  if (bytes < 1024) return `${bytes} B`;
  if (bytes < 1024 * 1024) return `${Math.round(bytes / 1024)} KB`;
  return `${(bytes / (1024 * 1024)).toFixed(1)} MB`;
}

/** Short local time ("14:05") for a message timestamp. */
export function formatTime(date: Date) {
  return date.toLocaleTimeString(undefined, { hour: '2-digit', minute: '2-digit' });
}

/** Pretty-prints any value as JSON; falls back to String() for cyclic or exotic values. */
export function toJson(value: unknown) {
  if (typeof value === 'string') return value;
  try {
    return JSON.stringify(value, null, 2) ?? String(value);
  } catch {
    return String(value);
  }
}

import { useCallback, useEffect, useRef, useState } from 'react';

/**
 * Copies text to the clipboard and exposes a short-lived `copied` flag for the button label.
 * The reset timer is cleared on unmount and on every new copy.
 */
export function useCopy(resetMs = 1600) {
  const [copied, setCopied] = useState(false);
  const timer = useRef<ReturnType<typeof setTimeout> | undefined>(undefined);

  useEffect(() => () => clearTimeout(timer.current), []);

  const copy = useCallback(
    async (text: string) => {
      try {
        await navigator.clipboard?.writeText(text);
      } catch {
        // Clipboard can be denied (insecure context, permissions); the flag still gives feedback.
      }
      setCopied(true);
      clearTimeout(timer.current);
      timer.current = setTimeout(() => setCopied(false), resetMs);
    },
    [resetMs],
  );

  return { copied, copy };
}

import type { ComponentDoc } from '@gntik-ai/ui';

export const doc: ComponentDoc = {
  name: 'ChatMessage',
  group: 'Display',
  status: 'beta',
  description:
    'One conversation turn for the roles user, assistant, system and tool: avatar, author, timestamp, body and hover/focus actions (copy, retry, thumbs feedback). While streaming it is aria-busy, hides its actions and shows typing dots until text arrives; ChatAnnouncer announces start and end once instead of every token.',
  pattern: 'article',
  keyboard: [
    ['Tab', 'Reaches each action in order (copy, retry, good, bad); focusing one reveals the action group'],
    ['Enter', 'Activates the focused action'],
    ['Space', 'Activates the focused action; thumbs toggle (aria-pressed)'],
  ],
  tokens: ['foreground', 'muted-foreground', 'secondary', 'card', 'border', 'primary', 'primary-text', 'destructive-text', 'focus-ring'],
};
